@Dao
interface UserDao {
    @Query("SELECT * FROM users WHERE name = :name") // validated against the User entity at compile time
    suspend fun findByName(name: String): List<User>
}

@Dao
interface NoteDao {
    @Query("SELECT * FROM note ORDER BY createdAt DESC")
    fun observeAll(): Flow<List<Note>>     // re-emits after any change to `note`

    @Query("SELECT * FROM note WHERE id = :id")
    suspend fun getById(id: Long): Note?   // one-shot

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsert(note: Note)
}

@Database(
    entities = [User::class],
    version = 2,
    exportSchema = true,
    autoMigrations = [AutoMigration(from = 1, to = 2, spec = Migration1To2::class)]
)
abstract class AppDatabase : RoomDatabase()

@RenameColumn(tableName = "User", fromColumnName = "name", toColumnName = "fullName")
